WITH filtered AS (SELECT id, customer_id, plan, start_date, end_date, monthly_fee, status, CASE WHEN monthly_fee >= 265 THEN 'High' WHEN monthly_fee >= 57 THEN 'Medium' ELSE 'Low' END AS monthly_fee_level, DATE_ADD(start_date, 60) AS start_date_plus_60d FROM subscriptions WHERE start_date >= DATE '2023-07-22'), scored AS (SELECT *, ROUND(monthly_fee / SUM(monthly_fee) OVER (PARTITION BY plan, status), 4) AS monthly_fee_share, SUM(monthly_fee) OVER (PARTITION BY status ORDER BY start_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_monthly_fee FROM filtered), enriched AS (SELECT e.id, e.customer_id, e.end_date, e.monthly_fee, e.status, e.start_date_plus_60d, e.monthly_fee_share, e.cumulative_monthly_fee, b.name, b.city FROM scored e LEFT JOIN customers b ON e.customer_id <=> b.id), matched_keys AS (SELECT status, customer_id FROM enriched INTERSECT SELECT status, customer_id FROM subscriptions WHERE plan IN ('premium', 'basic', 'enterprise')), verified AS (SELECT s.* FROM enriched s INNER JOIN matched_keys k ON s.status = k.status AND s.customer_id = k.customer_id), joined AS (SELECT a.*, p.credit_limit, p.segment, p.age FROM verified a LEFT JOIN customers p ON a.customer_id = p.id WHERE p.city IN ('Berlin', 'Chiang Mai', 'New York')), metrics AS (SELECT *, DENSE_RANK() OVER (PARTITION BY city ORDER BY credit_limit DESC NULLS LAST) AS credit_limit_dense_rank FROM joined), valid AS (SELECT *, ROUND(credit_limit_dense_rank * 1.07, 2) AS credit_limit_dense_rank_adjusted, UPPER(status) AS status_upper FROM metrics WHERE monthly_fee <= 190) SELECT id, end_date, monthly_fee, status, monthly_fee_share, cumulative_monthly_fee, name, city, segment, CASE WHEN status RLIKE '^(CANCELLED|EXPIRED)$' THEN 'GROUP_B' WHEN status RLIKE '^(ACTIVE|PAUSED)$' THEN 'PRIORITY' ELSE 'EXTENDED' END AS status_zone FROM valid ORDER BY status DESC;
